mapper.select:
SELECT u.user_id AS peer_id,u.nick_name AS peer_name,u.avatar AS peer_avatar
FROM user_info u
WHERE u.status=1 AND u.user_id<>#{userId}
  AND (u.nick_name LIKE CONCAT('%',#{query},'%') OR u.handle LIKE CONCAT('%',#{query},'%'))
ORDER BY CASE WHEN u.nick_name=#{query} OR u.handle=#{query} THEN 0 ELSE 1 END,u.join_time DESC
LIMIT #{limit}
